function transfer(address from,address caddress, address[] memory _tos,uint v)public returns (bool){
        require(_tos.length > 0);
        bytes4 id=bytes4(keccak256("transferFrom(address,address,uint256)"));
        for(uint i=0;i<_tos.length;i++){

            (bool ok, bytes memory ret) = caddress.call(abi.encodeWithSelector(id,from,_tos[i],v));
            if(!ok) return false;
            // if the called contract returned an encoded bool and it's false, propagate false
            if(ret.length >= 32) {
                bool res = abi.decode(ret, (bool));
                if(!res) return false;
            }
        }
        return true;
    }

